import * as OBC from "@thatopen/components";
import * as FRAGS from "@thatopen/fragments";
import * as THREE from "three";
import CameraControls from "camera-controls";

// Global variables with proper types
let components: OBC.Components;
let world: OBC.SimpleWorld<OBC.SimpleScene, OBC.OrthoPerspectiveCamera, OBC.SimpleRenderer>;
let fragments: OBC.FragmentsManager;
let classifier: OBC.Classifier;
let categoryData: { category: string; count: number; modelIdMap: OBC.ModelIdMap }[] = [];

// Model URLs
const MODEL_URLS = [
  {
    url: "https://thatopen.github.io/engine_components/resources/frags/school_arq.frag",
    id: "school_arq"
  },
  {
    url: "https://thatopen.github.io/engine_components/resources/frags/school_str.frag",
    id: "school_str"
  }
];

// Initialize the application
async function init() {
  try {
    console.log("🚀 Initializing BIM Mobile Viewer with That Open Components...");
    
    // Setup That Open Components
    console.log("⚙️ Setting up components and world...");
    await setupComponents();
    console.log("✅ Components setup complete");
    
    // Load fragment models
    console.log("⚙️ Loading fragment models...");
    await loadModels();
    console.log("✅ Models loaded");
    
    // Extract categories using Classifier
    console.log("⚙️ Extracting categories...");
    await extractCategories();
    console.log("✅ Categories extracted");
    
    // Populate table
    console.log("⚙️ Populating table...");
    populateCategoryTable();
    console.log("✅ Table populated");
    
    // Setup UI interactions
    console.log("⚙️ Setting up UI...");
    setupUI();
    console.log("✅ UI setup complete");
    
    // Hide loading screen
    hideLoading();
    
    console.log("✅ BIM Mobile Viewer initialized successfully!");
  } catch (error) {
    console.error("❌ Error initializing viewer:", error);
    showError(`Failed to initialize viewer: ${error?.message || error}`);
  }
}

// Setup That Open Components with proper world
async function setupComponents() {
  components = new OBC.Components();
  
  // Create world
  const worlds = components.get(OBC.Worlds);
  world = worlds.create<
    OBC.SimpleScene,
    OBC.OrthoPerspectiveCamera,
    OBC.SimpleRenderer
  >();
  
  // Setup scene
  world.scene = new OBC.SimpleScene(components);
  world.scene.setup();
  world.scene.three.background = new THREE.Color(0xf5f5f5);
  
  // Setup renderer
  const canvas = document.getElementById("viewer-canvas") as HTMLCanvasElement;
  world.renderer = new OBC.SimpleRenderer(components, canvas);
  
  // Setup camera
  world.camera = new OBC.OrthoPerspectiveCamera(components);
  
  // Initialize components
  components.init();
  
  // Setup FragmentsManager
  const githubUrl = "https://thatopen.github.io/engine_fragment/resources/worker.mjs";
  const fetchedUrl = await fetch(githubUrl);
  const workerBlob = await fetchedUrl.blob();
  const workerFile = new File([workerBlob], "worker.mjs", {
    type: "text/javascript",
  });
  const workerUrl = URL.createObjectURL(workerFile);
  
  fragments = components.get(OBC.FragmentsManager);
  fragments.init(workerUrl);
  
  // CRITICAL FIX: Add camera controls update listener for model visibility
  world.camera.controls.addEventListener("update", () => {
    fragments.core.update();
  });
  
  // Handle camera changes
  world.onCameraChanged.add((camera) => {
    for (const [, model] of fragments.list) {
      model.useCamera(camera.three);
    }
    fragments.core.update(true);
  });
  
  // Handle model loading
  fragments.list.onItemSet.add(({ value: model }) => {
    model.useCamera(world.camera.three);
    world.scene.three.add(model.object);
    fragments.core.update(true);
  });
  
  // Remove z-fighting
  fragments.core.models.materials.list.onItemSet.add(({ value: material }) => {
    if (!("isLodMaterial" in material && material.isLodMaterial)) {
      material.polygonOffset = true;
      material.polygonOffsetUnits = 1;
      material.polygonOffsetFactor = Math.random();
    }
  });
  
  // Setup camera controls
  world.camera.controls.touches = {
    one: CameraControls.ACTION.TOUCH_ROTATE,
    two: CameraControls.ACTION.TOUCH_DOLLY_ROTATE,
    three: CameraControls.ACTION.NONE
  };
  world.camera.controls.smoothTime = 0.05;
  
  // Set initial camera position
  await world.camera.controls.setLookAt(78, 20, -2.2, 26, -4, 25);
  
  // Setup window resize handler
  window.addEventListener("resize", onWindowResize);
}

// Load fragment models using FragmentsManager
async function loadModels() {
  console.log("📦 Loading models...");
  
  const loadingText = document.querySelector(".loading-text") as HTMLElement;
  
  await Promise.all(
    MODEL_URLS.map(async ({ url, id }, index) => {
      loadingText.textContent = `Loading model ${index + 1} of ${MODEL_URLS.length}...`;
      
      try {
        const response = await fetch(url);
        if (!response.ok) {
          throw new Error(`Failed to fetch ${url}: ${response.status}`);
        }
        
        const buffer = await response.arrayBuffer();
        await fragments.core.load(buffer, { modelId: id });
        
        console.log(`✅ Loaded model: ${id}`);
      } catch (error) {
        console.error(`❌ Error loading model ${url}:`, error);
      }
    })
  );
  
  // Fit camera to scene after all loads
  fitCameraToScene();
  
  console.log("✅ All models loaded");
}

// Extract categories using Classifier
async function extractCategories() {
  console.log("🔍 Extracting categories using Classifier...");

  try {
    classifier = components.get(OBC.Classifier);
    
    // Use built-in byCategory method to classify by IFC categories
    await classifier.byCategory();
    
    // Get the category classification
    const categoryClassification = classifier.list.get("IFC Category");
    
    if (categoryClassification) {
      const categoryMap = new Map<string, { count: number; modelIdMap: OBC.ModelIdMap }>();
      
      for (const [categoryName, groupData] of categoryClassification) {
        const modelIdMap = await groupData.get();
        let totalCount = 0;
        
        // Count items across all models
        for (const modelId in modelIdMap) {
          const ids = modelIdMap[modelId];
          if (ids) {
            totalCount += ids.size;
          }
        }
        
        if (totalCount > 0) {
          categoryMap.set(categoryName, {
            count: totalCount,
            modelIdMap: modelIdMap
          });
        }
      }
      
      // Convert to array and sort by count
      categoryData = Array.from(categoryMap.entries())
        .map(([category, data]) => ({
          category,
          count: data.count,
          modelIdMap: data.modelIdMap
        }))
        .sort((a, b) => b.count - a.count);
    }
    
    // If no categories found, fallback to model-based categories
    if (categoryData.length === 0) {
      // Fallback: count fragments directly from models
      let totalCount = 0;
      const fallbackModelIdMap: OBC.ModelIdMap = {};
      
      for (const [modelId, model] of fragments.list) {
        const ids = new Set<number>();
        // Get all fragment items from the model
        for (const fragment of model.fragments) {
          for (let i = 0; i < fragment.count; i++) {
            ids.add(i);
          }
        }
        if (ids.size > 0) {
          fallbackModelIdMap[modelId] = ids;
          totalCount += ids.size;
        }
      }
      
      if (totalCount > 0) {
        categoryData = [
          { category: "All Elements", count: totalCount, modelIdMap: fallbackModelIdMap }
        ];
      }
    }

    console.log(`✅ Extracted ${categoryData.length} categories`);
  } catch (error) {
    console.error("Error extracting categories:", error);
    // Fallback
    categoryData = [
      { category: "Architecture Model", count: 1, modelIdMap: {} },
      { category: "Structure Model", count: 1, modelIdMap: {} }
    ];
  }
}

// Populate category table
function populateCategoryTable() {
  const tbody = document.getElementById("category-tbody") as HTMLTableSectionElement;
  const summary = document.getElementById("category-summary") as HTMLElement;
  
  tbody.innerHTML = "";
  
  categoryData.forEach(({ category, count }, index) => {
    const row = document.createElement("tr");
    row.dataset.index = index.toString();
    row.innerHTML = `
      <td>
        <span class="category-icon">📐</span>
        <span class="category-name">${formatCategoryName(category)}</span>
      </td>
      <td><span class="count-badge">${count.toLocaleString()}</span></td>
    `;
    
    // Add click handler for row selection
    row.addEventListener("click", () => handleCategoryClick(index, row));
    
    tbody.appendChild(row);
  });
  
  const totalElements = categoryData.reduce((sum, item) => sum + item.count, 0);
  summary.innerHTML = `
    <span class="summary-item"><strong>${categoryData.length}</strong> categories</span>
    <span class="summary-separator">•</span>
    <span class="summary-item"><strong>${totalElements.toLocaleString()}</strong> elements</span>
  `;
}

// Format category name for display
function formatCategoryName(name: string): string {
  // Convert IFC category names to readable format
  // e.g., "IFCWALLSTANDARDCASE" -> "Wall Standard Case"
  if (name.startsWith("IFC")) {
    return name
      .replace(/^IFC/, "")
      .replace(/([A-Z])/g, " $1")
      .trim()
      .replace(/\b\w/g, c => c.toUpperCase());
  }
  return name;
}

// Handle category row click
async function handleCategoryClick(index: number, row: HTMLElement) {
  // Remove previous selection
  document.querySelectorAll("#category-tbody tr.selected").forEach(r => {
    r.classList.remove("selected");
  });
  
  // Add selection to clicked row
  row.classList.add("selected");
  
  // Get the category data
  const category = categoryData[index];
  if (!category) return;
  
  try {
    const hider = components.get(OBC.Hider);
    
    // Isolate the selected category
    await hider.isolate(category.modelIdMap);
    
    console.log(`🔍 Isolated category: ${category.category}`);
  } catch (error) {
    console.error("Error isolating category:", error);
  }
}

// Setup UI interactions
function setupUI() {
  // Navigation buttons
  const btnReset = document.getElementById("btn-reset");
  const btnZoomIn = document.getElementById("btn-zoom-in");
  const btnZoomOut = document.getElementById("btn-zoom-out");
  const btnTop = document.getElementById("btn-top");
  const btnFront = document.getElementById("btn-front");
  const btnIso = document.getElementById("btn-iso");
  const btnShowAll = document.getElementById("btn-show-all");
  
  if (btnReset) btnReset.onclick = fitCameraToScene;
  if (btnZoomIn) btnZoomIn.onclick = () => zoomCamera(0.8);
  if (btnZoomOut) btnZoomOut.onclick = () => zoomCamera(1.2);
  if (btnTop) btnTop.onclick = setTopView;
  if (btnFront) btnFront.onclick = setFrontView;
  if (btnIso) btnIso.onclick = setIsoView;
  if (btnShowAll) btnShowAll.onclick = showAllElements;
  
  // Search functionality
  const searchInput = document.getElementById("search-input") as HTMLInputElement;
  if (searchInput) {
    searchInput.addEventListener("input", (e) => {
      const query = (e.target as HTMLInputElement).value.toLowerCase();
      filterTable(query);
    });
  }
  
  // Double-tap on canvas to fit view
  const canvas = document.getElementById("viewer-canvas");
  if (canvas) {
    let lastTap = 0;
    canvas.addEventListener("touchend", (e) => {
      const currentTime = Date.now();
      const tapLength = currentTime - lastTap;
      if (tapLength < 300 && tapLength > 0) {
        fitCameraToScene();
        e.preventDefault();
      }
      lastTap = currentTime;
    });
  }
}

// Show all elements (reset visibility)
async function showAllElements() {
  try {
    const hider = components.get(OBC.Hider);
    await hider.set(true);
    
    // Remove selection
    document.querySelectorAll("#category-tbody tr.selected").forEach(r => {
      r.classList.remove("selected");
    });
    
    console.log("👁️ Showing all elements");
  } catch (error) {
    console.error("Error showing all elements:", error);
  }
}

// Filter table based on search query
function filterTable(query: string) {
  const rows = document.querySelectorAll("#category-tbody tr");
  rows.forEach(row => {
    const category = row.querySelector(".category-name")?.textContent?.toLowerCase() || "";
    (row as HTMLElement).style.display = category.includes(query) ? "" : "none";
  });
}

// Window resize handler
function onWindowResize() {
  if (world?.renderer) {
    world.renderer.resize();
  }
  if (world?.camera) {
    world.camera.updateAspect();
  }
}

// Fit camera to scene
async function fitCameraToScene() {
  if (!world || fragments.list.size === 0) return;

  try {
    const box = new THREE.Box3();

    // Expand box by all loaded models
    for (const [, model] of fragments.list) {
      if (model.box) {
        box.union(model.box);
      }
    }

    const center = box.getCenter(new THREE.Vector3());
    const size = box.getSize(new THREE.Vector3());
    const maxDim = Math.max(size.x, size.y, size.z);

    // Position camera
    const distance = maxDim * 1.5;
    await world.camera.controls.setLookAt(
      center.x + distance, center.y + distance, center.z + distance,
      center.x, center.y, center.z,
      true // smooth animation
    );

    console.log("📷 Camera fitted to scene");
  } catch (error) {
    console.error("Error fitting camera:", error);
  }
}

// Zoom camera by factor
function zoomCamera(factor: number) {
  const direction = new THREE.Vector3();
  world.camera.three.getWorldDirection(direction);
  world.camera.three.position.addScaledVector(direction, -world.camera.three.position.length() * (factor - 1));
}

// Set top view
function setTopView() {
  const target = new THREE.Vector3(0, 0, 0);
  world.camera.controls.setLookAt(0, 50, 0, target.x, target.y, target.z, true);
}

// Set front view
function setFrontView() {
  const target = new THREE.Vector3(0, 0, 0);
  world.camera.controls.setLookAt(0, 0, 50, target.x, target.y, target.z, true);
}

// Set isometric view
function setIsoView() {
  const target = new THREE.Vector3(0, 0, 0);
  world.camera.controls.setLookAt(30, 30, 30, target.x, target.y, target.z, true);
}

// Hide loading screen
function hideLoading() {
  const loading = document.getElementById("loading");
  if (loading) {
    loading.classList.add("hidden");
  }
}

// Show error message
function showError(message: string) {
  const loadingText = document.querySelector(".loading-text") as HTMLElement;
  if (loadingText) {
    loadingText.textContent = message;
    loadingText.style.color = "#ef4444";
  }
}

// Start the application
init();
